"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8807"],{64251(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.endereco_referencia.numero_tamanho","status":422,"titulo":"N\xfamero do endere\xe7o excede o tamanho permitido"},"descricao":{"codigo":"uniplus.endereco_referencia.numero_tamanho","requisitos":[],"oQueAconteceu":["O campo `numero` do endere\xe7o estruturado tem mais de 20 caracteres, contados depois de retirados os espa\xe7os das pontas. A mensagem \xe9 `Campo de endere\xe7o excede o tamanho m\xe1ximo de 20 caracteres.` O campo \xe9 opcional: ausente, nulo, vazio ou s\xf3 com espa\xe7os, ele n\xe3o \xe9 recusado.","O endere\xe7o estruturado \xe9 opcional no cadastro do campus, do local de oferta e da institui\xe7\xe3o (a sede): sem o objeto `endereco` no corpo da requisi\xe7\xe3o, nenhuma confer\xeancia dele ocorre. Com o objeto, a API confere os campos um de cada vez e para na primeira recusa, nesta ordem: CEP informado, CEP com 8 d\xedgitos, cidade do endere\xe7o (as recusas da fam\xedlia [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio)), tamanho dos textos (logradouro, n\xfamero, complemento, bairro e distrito), latitude, longitude, n\xedvel de resolu\xe7\xe3o informado, n\xedvel de resolu\xe7\xe3o dentro do vocabul\xe1rio, origem informada e tamanho da origem. Os cinco textos s\xe3o conferidos em sequ\xeancia, e s\xf3 o primeiro que passa do limite \xe9 recusado: com o logradouro e o bairro acima do limite, a resposta traz s\xf3 a recusa do logradouro, e a do bairro aparece depois que o logradouro for corrigido. Os limites s\xe3o 200 caracteres para o logradouro, 20 para o n\xfamero, 100 para o complemento e 150 para o bairro e para o distrito.","A recusa vem na lista `errors` da resposta, com `field` igual a `endereco`, ao lado das recusas dos outros campos do mesmo cadastro, que s\xe3o conferidos no mesmo pedido. O `code` da resposta \xe9 o da primeira recusa da lista, e as recusas dos campos do pr\xf3prio cadastro (como `sigla`, `nome` e a cidade) v\xeam antes da do endere\xe7o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, estas confer\xeancias v\xeam antes da busca do registro: um `{id}` que n\xe3o existe, enviado com endere\xe7o recusado, recebe esta recusa, e s\xf3 o corpo aceito chega \xe0 resposta de [campus n\xe3o encontrado](/erros/uniplus.configuracao.campus.nao_encontrado), de [local de oferta n\xe3o encontrado](/erros/uniplus.configuracao.local_oferta.nao_encontrado) ou de [institui\xe7\xe3o n\xe3o encontrada](/erros/uniplus.organizacao.instituicao.nao_encontrada)."],"comoResolver":["Reduza o `numero` para no m\xe1ximo 20 caracteres, ou retire o campo do endere\xe7o, e envie o pedido de novo."],"ondeAparece":["Cria\xe7\xe3o de um campus","Atualiza\xe7\xe3o de um campus","Cria\xe7\xe3o de um local de oferta","Atualiza\xe7\xe3o de um local de oferta","Cria\xe7\xe3o da institui\xe7\xe3o","Atualiza\xe7\xe3o da institui\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Endereco referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);